          >
            {{ category }}
          </v-chip>
        </div>
      </section>

      <div v-if="loading" class="status-row glass-panel">
        <v-progress-circular indeterminate color="#a855f7" size="28" />
        <span>Loading wallpapers...</span>
      </div>

    <div
      v-else-if="filteredWallpapers.length > 0"
      class="grid-wrap"
    >
      <v-card
        v-for="wallpaper in filteredWallpapers"
        :key="wallpaper.id"
        class="wall-card"
        :class="{ 'wall-card--active': wallpaper.id === activeWallpaperId }"
        elevation="0"
        @click="openPreview(wallpaper)"
      >
        <v-chip
          v-if="wallpaper.id === activeWallpaperId"
          class="active-chip"
          color="success"
          size="small"
        >
          Active
        </v-chip>
        <v-img
          :src="displayImageUrl(wallpaper.imageUrl)"
          :alt="wallpaper.title"
          cover
          height="260"
          class="wall-image"
        />
        <div class="wall-overlay" />
        <div class="wall-text">
          <h3>{{ wallpaper.title }}</h3>
          <p>{{ wallpaper.category }} </p>
      
        </div>
      </v-card>
    </div>

    <v-alert
      v-else
      type="info"
      variant="tonal"
      density="comfortable"
      class="mt-4 glass-alert"
      rounded="xl"
    >
      No wallpapers found for {{ selectedCategory }}.
    </v-alert>

    <WallpaperPreviewDialog
