      :wallpaper="selectedWallpaper"
      :downloading="!!downloadingId"
      @download="downloadFromPreview"
    />

    <!-- Upload wallpaper dialog -->
    <v-dialog v-model="uploadOpen" max-width="560" persistent>
      <v-card class="upload-card" rounded="xl">
        <div class="upload-header">
          <div class="upload-title-icon" aria-hidden="true">
            <v-icon icon="mdi-image-plus" size="22" color="#fff" />
          </div>
          <div class="upload-header-text">
            <v-card-title class="upload-title pa-0">Add Wallpaper</v-card-title>
            <p class="upload-hint">
              Pick an image or paste a URL. The image URL is saved and shown in the list.
            </p>
          </div>
        </div>

        <v-card-text class="upload-card-text">
          <v-form ref="uploadFormRef" class="upload-form-fields" @submit.prevent="submitUpload">
            <v-text-field
              v-model="uploadForm.wallpaper_name"
              label="Wallpaper name"
              placeholder="Wallpaper name"
              variant="outlined"
              density="comfortable"
              rounded="lg"
              hide-details="auto"
              bg-color="#ffffff"
              class="upload-field"
              :rules="[rules.required]"
              @update:model-value="syncUrlFromNameAndFile"
            />
            <v-select
              v-model="uploadForm.category"
              :items="uploadCategories"
              label="Category"
              variant="outlined"
              density="comfortable"
              rounded="lg"
              hide-details="auto"
              bg-color="#ffffff"
              class="upload-field"
              :rules="[rules.required]"
            />
            <v-file-input
              v-model="uploadFile"
              label="Choose image"
              placeholder="Choose image"
              accept="image/png,image/jpeg,image/webp"
              variant="outlined"
              density="comfortable"
              rounded="lg"
              hide-details="auto"
              bg-color="#ffffff"
              prepend-icon=""
              prepend-inner-icon="mdi-paperclip"
              class="upload-field upload-field--file"
              show-size
              @update:model-value="onUploadFileChange"
            />
            <v-img
              v-if="uploadPreviewSrc"
              :src="uploadPreviewSrc"
              max-height="160"
              contain
              class="upload-preview"
            />
            <!-- <v-text-field
              v-model="uploadForm.s3_url"
              label="Image URL"
              variant="outlined"
              density="comfortable"
              :rules="[rules.required, rules.url]"
              hint="Auto-filled from image name; edit if your S3 path is different"
              persistent-hint
            /> -->
          
          </v-form>
        </v-card-text>
        <v-card-actions class="upload-actions">
          <v-btn variant="text" :disabled="uploading" @click="closeUploadDialog">
            Cancel
          </v-btn>
          <v-spacer />
          <v-btn
            class="primary-gradient-btn"
            variant="flat"
            rounded="xl"
            :loading="uploading"
            @click="submitUpload"
          >
            Add to catalog
          </v-btn>
        </v-card-actions>
      </v-card>
    </v-dialog>

    </v-container>
  </div>
</template>

<script>
import logo from '@/assets/wall-labs-logo.png'
import background from '@/assets/login-background.png'
import WallpaperPreviewDialog from '@/components/WallpaperPreviewDialog.vue'
import {
  addWallpaper,
  listWallpapers
} from '@/services/wallLabsApi'
import {
  buildS3Key,
  getPublicS3Url,
  uploadToS3,
  normalizeS3PublicUrl,
  getDisplayImageUrl
} from '@/services/publicS3Upload'
import {
  getAllLocalWallpaperRecords,
  recordToObjectUrl,
  saveLocalWallpaperImage
} from '@/services/localWallpaperStore'
import { clearAuthSession } from '@/services/authSession'
import { showAppError, showAppSuccess } from '@/services/appSnackbar'

const STORAGE_KEY = 'wallLabsActiveWallpaper'
const CATEGORIES = [
  'All',
  'Anime-style',
  'Nature',
  'AMOLED',
  'Abstract',
  'Gaming',
  'Sci-Fi'
]

function parseResponsePayload(payload) {
  if (Array.isArray(payload)) return payload
  if (Array.isArray(payload?.wallpapers)) return payload.wallpapers
  if (Array.isArray(payload?.Wallpapers)) return payload.Wallpapers
  if (Array.isArray(payload?.items)) return payload.items
  if (Array.isArray(payload?.data)) return payload.data
  if (typeof payload?.body === 'string') {
    try {
      const parsed = JSON.parse(payload.body)
      return Array.isArray(parsed)
        ? parsed
        : parsed?.wallpapers || parsed?.Wallpapers || parsed?.items || parsed?.data || []
    } catch {
      return []
    }
  } 
  return []
}

function normalizeCategory(rawCategory) {
  const value = String(rawCategory || '').trim()
  if (CATEGORIES.includes(value)) return value

  const lower = value.toLowerCase()
  if (lower.includes('anime')) return 'Anime-style'
  if (lower.includes('nature')) return 'Nature'
  if (lower.includes('amoled')) return 'AMOLED'
  if (lower.includes('abstract')) return 'Abstract'
  if (lower.includes('gaming') || lower.includes('game')) return 'Gaming'
  if (lower.includes('sci') || lower.includes('cyber')) return 'Sci-Fi'
  return value || 'Abstract'
}

function normalizeWallpaper(item, index) {
  const rawUrl = String(
    item.s3_url ||
      item.s3Url ||
      item.imageUrl ||
      item.image ||
      item.url ||
      item.wallpaperUrl ||
      ''
  ).trim()

  const imageUrl = normalizeS3PublicUrl(rawUrl) || rawUrl

  return {
    id: item.wallpaper_id || item.wallpaperId || item.id || item._id || `wall-${index}`,
    title: item.wallpaper_name || item.title || item.name || `Wallpaper ${index + 1}`,
    imageUrl,
    category: normalizeCategory(item.category || item.type || item.style || item.tag),
    status: String(item.status || '').toUpperCase()
  }
}

function dedupeWallpapers(items) {
  const byId = new Map()
  for (const item of items) {
    byId.set(item.id, item)
  }
  return [...byId.values()]
}

export default {
  name: 'LandingPage',
  components: {
    WallpaperPreviewDialog
  },
  data() {
    return {
      logo,
      background,
      categories: CATEGORIES,
      selectedCategory: 'All',
      wallpapers: [],
      loading: false,
      previewOpen: false,
      selectedWallpaper: null,
      activeWallpaper: null,
      activeWallpaperId: null,
      downloadingId: null,
      uploadOpen: false,
      uploading: false,
      uploadFile: null,
      uploadPreview: '',
      localObjectUrls: [],
      uploadForm: {
        wallpaper_name: '',
        category: 'Nature',
        s3_url: ''
      },
      rules: {
        required: (v) => !!String(v || '').trim() || 'Required',
        url: (v) =>
          /^https?:\/\/.+/i.test(String(v || '').trim()) || 'Enter a valid URL'
      }
    }
  },
  computed: {
    uploadCategories() {
      return CATEGORIES.filter((c) => c !== 'All')
    },
    filteredWallpapers() {
      const list = Array.isArray(this.wallpapers) ? this.wallpapers : []
      if (this.selectedCategory === 'All') {
        return list
      }
      return list.filter(
        (wallpaper) => wallpaper.category === this.selectedCategory
      )
    },
    uploadPreviewSrc() {
      if (this.uploadPreview) return this.uploadPreview
      const url = String(this.uploadForm.s3_url || '').trim()
      return /^https?:\/\/.+/i.test(url) ? url : ''
    }
  },
  watch: {
    previewOpen(isOpen) {
      if (!isOpen) {
        this.selectedWallpaper = null
      }
    }
  },
  mounted() {
    this.loadActiveWallpaper()
    this.fetchWallpapers()
  },
  methods: {
    displayImageUrl(imageUrl) {
      return getDisplayImageUrl(imageUrl)
    },
    goToLogin() {
      clearAuthSession()
      this.$router.push('/')
    },
    loadActiveWallpaper() {
      try {
        const saved = localStorage.getItem(STORAGE_KEY)
        if (!saved) return
        const parsed = JSON.parse(saved)
        if (parsed?.id && parsed?.imageUrl) {
          this.activeWallpaper = parsed
          this.activeWallpaperId = parsed.id
        }
      } catch {
        localStorage.removeItem(STORAGE_KEY)
      }
    },
    openPreview(wallpaper) {
      if (!wallpaper) return
      this.selectedWallpaper = wallpaper
      this.previewOpen = true
    },
    async downloadFromPreview(wallpaper) {
      const item = wallpaper || this.selectedWallpaper
      if (!item || this.downloadingId) return

      this.downloadingId = item.id
      try {
        const openedInTab = await this.downloadWallpaperImage(item)
        showAppSuccess(
          openedInTab
            ? `"${item.title}" opened — right-click and Save image as.`
            : `"${item.title}" downloaded.`
        )
      } catch {
        showAppError('Could not download. Check that the image URL is public.')
      } finally {
        this.downloadingId = null
      }
    },
    async downloadWallpaperImage(wallpaper) {
      const directUrl = String(wallpaper?.imageUrl || '').trim()
      if (!directUrl) throw new Error('No image URL')

      const fetchUrl = getDisplayImageUrl(directUrl)
      const safeName =
        String(wallpaper.title || 'wallpaper').replace(/[^\w\s-]/g, '').trim() ||
        'wallpaper'
      const extension =
        directUrl.match(/\.(png|jpe?g|webp|gif)$/i)?.[1]?.toLowerCase() || 'png'

      let response
      try {
        response = await fetch(fetchUrl)
      } catch {
        response = await fetch(directUrl)
      }

      if (!response.ok) {
        window.open(directUrl, '_blank', 'noopener,noreferrer')
        return true
      }

      const blob = await response.blob()
      const blobUrl = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = blobUrl
      link.download = `${safeName}.${extension}`
      document.body.appendChild(link)
      link.click()
      link.remove()
      URL.revokeObjectURL(blobUrl)
      return false
    },
    openUploadDialog() {
      this.uploadOpen = true
    },
    closeUploadDialog() {
      this.uploadOpen = false
      this.uploading = false
      this.uploadFile = null
      this.revokeUploadPreview()
      this.uploadForm = {
        wallpaper_name: '',
        category: 'Nature',
        s3_url: ''
      }
    },
    revokeUploadPreview() {
      if (this.uploadPreview?.startsWith('blob:')) {
        URL.revokeObjectURL(this.uploadPreview)
      }
      this.uploadPreview = ''
    },
    getSelectedFile() {
      const file = Array.isArray(this.uploadFile)
        ? this.uploadFile[0]
        : this.uploadFile
      return file || null
    },
    syncUrlFromNameAndFile() {
      if (!this.uploadForm.wallpaper_name) return
      const file = this.getSelectedFile()
      const key = buildS3Key(this.uploadForm.wallpaper_name, file)
      this.uploadForm.s3_url = getPublicS3Url(key)
    },
    onUploadFileChange(files) {
      this.revokeUploadPreview()
      const file = Array.isArray(files) ? files[0] : files
      if (!file) return

      if (!this.uploadForm.wallpaper_name) {
        this.uploadForm.wallpaper_name = file.name.replace(/\.[^.]+$/, '')
      }

      this.uploadPreview = URL.createObjectURL(file)
      this.syncUrlFromNameAndFile()
    },
    revokeLocalObjectUrls() {
      for (const url of this.localObjectUrls) {
        if (url?.startsWith('blob:')) {
          URL.revokeObjectURL(url)
        }
      }
      this.localObjectUrls = []
    },
    async enrichWallpapersWithLocalImages(wallpapers) {
      this.revokeLocalObjectUrls()
      const records = await getAllLocalWallpaperRecords()
      const localUrlById = {}

      for (const record of records) {
        const objectUrl = recordToObjectUrl(record)
        if (objectUrl) {
          localUrlById[record.id] = objectUrl
          this.localObjectUrls.push(objectUrl)
        }
      }

      return wallpapers.map((wallpaper) => {
        const localUrl = localUrlById[wallpaper.id]
        if (!localUrl) return wallpaper
        return { ...wallpaper, imageUrl: localUrl }
      })
    },
    async submitUpload() {
      const name = this.uploadForm.wallpaper_name.trim()
      const category = this.uploadForm.category
      const file = this.getSelectedFile()
      const s3Key = buildS3Key(name, file)
      const s3Url = getPublicS3Url(s3Key)
      this.uploadForm.s3_url = s3Url

      if (!name || !category) {
        showAppError('Name and category are required.')
        return
      }

      if (!file) {
        showAppError('Choose an image file.')
        return
      }

      this.uploading = true
      try {
        const uploadedUrl = normalizeS3PublicUrl(await uploadToS3(file, s3Key))

        const result = await addWallpaper({
          wallpaper_name: name,
          category,
          s3_url: uploadedUrl || s3Url
        })

        const wallpaperId = result?.wallpaper_id
        if (wallpaperId && file) {
          await saveLocalWallpaperImage(wallpaperId, file)
        }

        const newWallpaper = {
          id: wallpaperId || `local-${Date.now()}`,
          title: name,
          imageUrl: uploadedUrl,
          category,
          status: 'LIVE'
        }

        this.selectedCategory = 'All'
        this.closeUploadDialog()
        await this.fetchWallpapers()

        const exists = this.wallpapers.some((w) => w.id === newWallpaper.id)
        if (!exists && newWallpaper.id) {
          const enriched = await this.enrichWallpapersWithLocalImages([
            newWallpaper,
            ...this.wallpapers
          ])
          this.wallpapers = dedupeWallpapers(enriched)
        }

        showAppSuccess(`"${name}" uploaded and added.`)
      } catch (error) {
        showAppError(error.message || 'Failed to add wallpaper.')
      } finally {
        this.uploading = false
      }
    },
    async fetchWallpapers() {
      this.loading = true

      try {
        const rawData = await listWallpapers()
        const wallpapers = parseResponsePayload(rawData)

        const normalized = dedupeWallpapers(
          wallpapers
            .map(normalizeWallpaper)
            .filter((item) => item.status === 'LIVE')
            .filter((item) => item.imageUrl)
        )

        this.wallpapers = await this.enrichWallpapersWithLocalImages(normalized)
      } catch (error) {
        showAppError(error.message || 'Failed to load wallpapers.')
        this.wallpapers = []
      } finally {
        this.loading = false
      }
    }
  },
  beforeUnmount() {
    this.revokeUploadPreview()
    this.revokeLocalObjectUrls()
  }
}
</script>

